import { z } from 'zod';

/**
 * `/config.json` is generated by Caddy at container start. Optional values are
 * substituted as empty strings when their environment variable is unset, so
 * blank strings become `undefined` before validation.
 */
const optionalUrl = z.preprocess(
  (value) =>
    typeof value === 'string' && value.trim() === '' ? undefined : value,
  z.url().optional(),
);

export const runtimeConfigSchema = z.object({
  apiBaseUrl: z.url({ protocol: /^https?$/ }),
  dashboardApiUrl: optionalUrl,
  storageOrigin: optionalUrl,
});

export type RuntimeConfig = z.infer<typeof runtimeConfigSchema>;

export type RuntimeConfigResult =
  | { ok: true; config: RuntimeConfig }
  | { ok: false; message: string };

let cached: RuntimeConfigResult | undefined;
let pending: Promise<RuntimeConfigResult> | undefined;

/** Validates a parsed `/config.json` document, throwing on the first problems. */
export function parseRuntimeConfig(input: unknown): RuntimeConfig {
  const parsed = runtimeConfigSchema.safeParse(input);
  if (parsed.success) return parsed.data;

  const issues = parsed.error.issues
    .map((issue) => `${issue.path.join('.') || 'config'}: ${issue.message}`)
    .join('; ');
  throw new Error(issues);
}

/**
 * Loads and validates `/config.json`. The root route awaits this before any
 * route renders. A failed load is cached until the page reloads, so a broken
 * deployment keeps showing the error page instead of retrying on navigation.
 */
export function loadRuntimeConfig(): Promise<RuntimeConfigResult> {
  if (cached) return Promise.resolve(cached);
  if (!pending) {
    pending = readRuntimeConfig().then((result) => {
      cached = result;
      pending = undefined;
      return result;
    });
  }
  return pending;
}

export function getRuntimeConfig(): RuntimeConfig | undefined {
  return cached?.ok ? cached.config : undefined;
}

/**
 * The settled load result, for the root error page. `undefined` means the load
 * has not finished; the router's hydration hook settles it before first render
 * and the unit tests reach it through the root `beforeLoad`.
 */
export function getRuntimeConfigResult(): RuntimeConfigResult | undefined {
  return cached;
}

/** Clears the module cache so tests can exercise each load in isolation. */
export function resetRuntimeConfig(): void {
  cached = undefined;
  pending = undefined;
}

async function readRuntimeConfig(): Promise<RuntimeConfigResult> {
  // SPA mode prerenders the HTML shell in Node, where /config.json is not
  // served. The router's client `hydrate` hook replaces this placeholder with
  // the container's real values before the first browser render.
  if (import.meta.env.SSR) {
    return { ok: true, config: { apiBaseUrl: '' } };
  }

  try {
    const response = await fetch(
      new URL('/config.json', globalThis.location.origin),
      {
        cache: 'no-store',
        headers: { accept: 'application/json' },
      },
    );
    if (!response.ok) {
      throw new Error(`HTTP ${String(response.status)}`);
    }
    return { ok: true, config: parseRuntimeConfig(await response.json()) };
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return { ok: false, message: `Could not load /config.json: ${reason}` };
  }
}
